import sqlite3
con=sqlite3.connect('data/app.db')
for row in con.execute(\"SELECT name FROM sqlite_master WHERE type='table'\"):
    print(row[0])
    print(list(con.execute(f'PRAGMA table_info({row[0]})')))
    if row[0] == 'schema_migrations': print(list(con.execute('SELECT * FROM schema_migrations')))
    if row[0] == 'customers': print(list(con.execute('SELECT * FROM customers')))
